import json, glob, os, sys, datetime, re
D='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/subagents/workflows/wf_603242ca-111/'
def ts(s): return datetime.datetime.fromisoformat(s.replace('Z','+00:00'))
pat=re.compile(sys.argv[1]) if len(sys.argv)>1 else None
for meta in sorted(glob.glob(D+'agent-*.meta.json'), key=lambda p: json.load(open(p.replace('.meta.json','.jsonl').replace('.jsonl','.meta.json')))['description']):
