            for c in msg['content']:
                if isinstance(c,dict) and c.get('type')=='tool_result' and c.get('tool_use_id') in uses:
                    t0,cmd,bg,to=uses.pop(c['tool_use_id'])
                    dur=(ts(t)-t0).total_seconds()
                    if pat is None or pat.search(cmd):
                        out.append((t0,dur,bg,cmd))
    if out:
        print("=== %s" % m['description'])
        for t0,dur,bg,cmd in out:
            print("  %s %5.0fs %s %s" % (t0.strftime('%H:%M:%S'), dur, 'BG' if bg else '  ', cmd.replace('\n',' ; ')[:230]))
EOF
